&quot;delivery_cost&quot;: 16
},
&quot;applied_rules&quot;: [&quot;M.1&quot;, &quot;M.2&quot;, &quot;M.3&quot;, &quot;M.4&quot;, &quot;M.5&quot;]
}
                          
                                                
                  
                              
                

