                              输出
                              true
                          
                                                
                  
                                                        
                      示例3
                      
                          
                              输入
                              [2,1,-3]
                          
                          
                              输出
                              true
                          
                                                
                  
                                                        
                      示例4
                      
                          
                              输入
                              [1,1,1,2,-1,1,-3]
                          
                          
                              输出
                              false

